'use strict';
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const zlib = require('node:zlib');
const {installLocalDshBundle} = require('../src/local-dsh-bundle');
const realSource=path.resolve(__dirname,'../vendor/dsh-x-magpie-0.7.2.tgz');
function setup(t) { const root=fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()),'dsh-admission-')); t.after(()=>{function unlock(dir){fs.chmodSync(dir,0o700);for(const n of fs.readdirSync(dir)){const p=path.join(dir,n);if(fs.lstatSync(p).isDirectory())unlock(p);}}unlock(root);fs.rmSync(root,{recursive:true,force:true});}); return root; }
function archive(name,type='0',content='') {
 const h=Buffer.alloc(512); h.write(name); h.write('0000644\0',100); h.write('0000000\0',108); h.write('0000000\0',116); h.write(Buffer.byteLength(content).toString(8).padStart(11,'0')+'\0',124); h.fill(32,148,156); h.write(type,156); h.write('ustar\0',257); let sum=0; for(const b of h) sum+=b; h.write(sum.toString(8).padStart(6,'0')+'\0 ',148); return zlib.gzipSync(Buffer.concat([h,Buffer.from(content),Buffer.alloc((512-Buffer.byteLength(content)%512)%512),Buffer.alloc(1024)]));
}
function fixture(root) { const dir=path.join(root,'source');fs.mkdirSync(dir);fs.mkdirSync(path.join(dir,'dist'));fs.writeFileSync(path.join(dir,'package.json'),JSON.stringify({name:'dsh-x-test',version:'1.0.0',exports:'./dist/index.js',dsh:{bundle:{patch:'./cordis.patch.yml'}},scripts:{install:'touch /tmp/MUST-NOT-RUN'}}));fs.writeFileSync(path.join(dir,'cordis.patch.yml'),'plugins: {}\n');fs.writeFileSync(path.join(dir,'dist/index.js'),'export const inject = ["credentials"]; throw new Error("must never execute");');return dir; }
test('real ecosystem tarball admitted and runtime digest independently verified',async t=>{const root=setup(t); const r=await installLocalDshBundle({sourcePath:realSource,storeRoot:path.join(root,'store'),expectedPackageName:'@straydragon/dsh-x-magpie',expectedVersion:'0.7.2'});assert.deepEqual(r.requiredServices,['webServer','configEditor','credentials']);assert.equal(require('../src/bundle-fingerprint').fingerprintBundle(r.bundlePath).sha256,r.bundleSha256);assert.equal(fs.statSync(path.join(r.bundlePath,'dist/index.js')).mode&0o777,0o400);assert.equal(JSON.parse(fs.readFileSync(path.join(path.dirname(r.bundlePath),'receipt.json'))).bundleSha256,r.bundleSha256);});
test('directory becomes owned snapshot, never executes module or lifecycle, pins reject mutations',async t=>{const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store');const first=await installLocalDshBundle({sourcePath,storeRoot}); fs.writeFileSync(path.join(sourcePath,'dist/index.js'),'export const inject = ["webServer"];');assert.match(fs.readFileSync(path.join(first.bundlePath,'dist/index.js'),'utf8'),/must never execute/);await assert.rejects(installLocalDshBundle({sourcePath,storeRoot,expectedSourceSha256:first.sourceSha256}),/digest pin mismatch/);const second=await installLocalDshBundle({sourcePath,storeRoot});assert.notEqual(first.bundlePath,second.bundlePath);assert.deepEqual(first.requiredServices,['credentials']);});
for(const [name,type] of [['package/../../escape','0'],['/outside','0'],['package/link','2'],['package/hard','1'],['package/device','3'],['package/fifo','6'],['package/pax','x'],['package\\escape','0']])test(`reject archive ${name} type ${type}`,async t=>{const root=setup(t),sourcePath=path.join(root,'bad.tgz');fs.writeFileSync(sourcePath,archive(name,type));await assert.rejects(installLocalDshBundle({sourcePath,storeRoot:path.join(root,'store')}));assert.equal(fs.existsSync(path.join(root,'store')),false);});
test('reject symlink, hardlink, missing exports, nonprivate store',async t=>{const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store');fs.symlinkSync('package.json',path.join(sourcePath,'link'));await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),/links/);fs.unlinkSync(path.join(sourcePath,'link'));fs.linkSync(path.join(sourcePath,'package.json'),path.join(sourcePath,'hard'));await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),/links/);fs.unlinkSync(path.join(sourcePath,'hard'));fs.writeFileSync(path.join(sourcePath,'dist/index.js'),'export const inject = [];');fs.mkdirSync(storeRoot,{mode:0o755});await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),/private/);fs.rmSync(path.join(sourcePath,'dist/index.js'));await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),/missing export/);});
test('source mutation during fingerprint rejects and removes partial admission',async t=>{const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store');const runtimeModule={fingerprintBundle(...args){const result=require('../src/bundle-fingerprint').fingerprintBundle(...args);fs.writeFileSync(path.join(sourcePath,'dist/index.js'),'export const inject = [];');return result;}};await assert.rejects(installLocalDshBundle({sourcePath,storeRoot,runtimeModule}),/source changed/);assert.deepEqual(fs.readdirSync(storeRoot),[]);});
test('reject checksum tampering, truncated tar, expansion limit and identity mismatch',async t=>{const root=setup(t),sourcePath=path.join(root,'bad.tgz'),storeRoot=path.join(root,'store');const data=zlib.gunzipSync(archive('package/file'));data[0]^=1;fs.writeFileSync(sourcePath,zlib.gzipSync(data));await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),/checksum/);fs.writeFileSync(sourcePath,zlib.gzipSync(Buffer.alloc(12)));await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),/truncated/);fs.writeFileSync(sourcePath,zlib.gzipSync(Buffer.alloc(32*1024*1024+1)));await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}));await assert.rejects(installLocalDshBundle({sourcePath:realSource,storeRoot,expectedVersion:'0.0.0'}),/identity pin/);});
for (const [code,evidence] of [['export const apply = () => {};','not-declared'],['export const inject = derive(); throw new Error("never import");','unknown'],["export const inject = ['credentials'];",'unknown']]) test(`inert admission accepts ${evidence} metadata`,async t=>{const root=setup(t),sourcePath=fixture(root);fs.writeFileSync(path.join(sourcePath,'dist/index.js'),code);const manifest=JSON.parse(fs.readFileSync(path.join(sourcePath,'package.json')));manifest.dependencies={cordis:'^3.0.0'};fs.writeFileSync(path.join(sourcePath,'package.json'),JSON.stringify(manifest));const r=await installLocalDshBundle({sourcePath,storeRoot:path.join(root,'store')});assert.equal(r.requiredServicesEvidence,evidence);assert.deepEqual(r.requiredServices,[]);assert.equal(r.runtimeDependenciesStatus,'not-resolved');assert.deepEqual(r.runtimeDependencies,{dependencies:{cordis:'^3.0.0'}});});
test('directory skips repository metadata and installed dependencies',async t=>{const root=setup(t),sourcePath=fixture(root);for(const name of ['.git','node_modules']){fs.mkdirSync(path.join(sourcePath,name));fs.symlinkSync('/must-not-read',path.join(sourcePath,name,'outside'));}const r=await installLocalDshBundle({sourcePath,storeRoot:path.join(root,'store')});assert.equal(fs.existsSync(path.join(r.bundlePath,'.git')),false);assert.equal(fs.existsSync(path.join(r.bundlePath,'node_modules')),false);assert.equal(r.runtimeDependenciesStatus,'none-declared');});
test('promotion keeps root writable until rename, then seals all directories',async t=>{
 const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store'),rename=fs.renameSync;let promoted=false;
 fs.renameSync=function(from,to){if(path.dirname(from)===storeRoot&&path.basename(from).startsWith('.admit-')){promoted=true;assert.equal(fs.statSync(from).mode&0o777,0o700,'sealed staging root is not portable');assert.equal(fs.statSync(path.join(from,'bundle')).mode&0o777,0o500);}return rename.call(fs,from,to);};
 let receipt;try{receipt=await installLocalDshBundle({sourcePath,storeRoot});}finally{fs.renameSync=rename;}
 assert(promoted);for(const dir of [path.dirname(receipt.bundlePath),receipt.bundlePath,path.join(receipt.bundlePath,'dist')])assert.equal(fs.statSync(dir).mode&0o777,0o500);assert.deepEqual(fs.readdirSync(storeRoot),[path.basename(path.dirname(receipt.bundlePath))]);
});
test('failed promotion retains original error, cleans sealed stage and preserves earlier admission',async t=>{
 const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store'),previous=await installLocalDshBundle({sourcePath,storeRoot}),rename=fs.renameSync,original=Object.assign(new Error('owned promotion denied'),{code:'EACCES'});
 fs.renameSync=function(from,to){if(path.dirname(from)===storeRoot&&path.basename(from).startsWith('.admit-'))throw original;return rename.call(fs,from,to);};
 try{await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),e=>e===original);}finally{fs.renameSync=rename;}
 assert.deepEqual(fs.readdirSync(storeRoot),[path.basename(path.dirname(previous.bundlePath))]);assert.equal(require('../src/bundle-fingerprint').fingerprintBundle(previous.bundlePath).sha256,previous.bundleSha256);
});
test('failed final seal cleans the newly promoted directory',async t=>{
 const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store'),chmod=fs.chmodSync,original=new Error('final seal denied');
 fs.chmodSync=function(target,mode){if(path.dirname(target)===storeRoot&&!path.basename(target).startsWith('.admit-')&&mode===0o500)throw original;return chmod.call(fs,target,mode);};
 try{await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),e=>e===original);}finally{fs.chmodSync=chmod;}
 assert.deepEqual(fs.readdirSync(storeRoot),[]);
});
test('secondary cleanup failure does not mask original admission failure',async t=>{
 const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store'),rename=fs.renameSync,rm=fs.rmSync,original=new Error('original promotion failure'),cleanup=new Error('secondary cleanup failure');
 fs.renameSync=function(from,to){if(path.dirname(from)===storeRoot&&path.basename(from).startsWith('.admit-'))throw original;return rename.call(fs,from,to);};fs.rmSync=function(target,options){if(path.dirname(target)===storeRoot&&path.basename(target).startsWith('.admit-'))throw cleanup;return rm.call(fs,target,options);};
 try{await assert.rejects(installLocalDshBundle({sourcePath,storeRoot}),e=>e===original&&e.cleanupError===cleanup);}finally{fs.renameSync=rename;fs.rmSync=rm;}
 assert.equal(fs.readdirSync(storeRoot).length,1);assert(fs.readdirSync(storeRoot)[0].startsWith('.admit-'));
});
test('failed admission cleanup never follows a link outside its owned stage',async t=>{
 const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store'),outside=path.join(root,'unrelated');fs.mkdirSync(outside,{mode:0o500});const runtimeModule={fingerprintBundle(bundle,options){const r=require('../src/bundle-fingerprint').fingerprintBundle(bundle,options);fs.symlinkSync(outside,path.join(bundle,'outside'));fs.writeFileSync(path.join(sourcePath,'dist/index.js'),'export const changed = true;');return r;}};
 await assert.rejects(installLocalDshBundle({sourcePath,storeRoot,runtimeModule}),/source changed/);assert.deepEqual(fs.readdirSync(storeRoot),[]);assert.equal(fs.statSync(outside).mode&0o777,0o500);
});
test('cleanup refuses a replacement stage inode and preserves unrelated contents',async t=>{
 const root=setup(t),sourcePath=fixture(root),storeRoot=path.join(root,'store');let replacement;const runtimeModule={fingerprintBundle(bundle,options){const r=require('../src/bundle-fingerprint').fingerprintBundle(bundle,options),stage=path.dirname(bundle);fs.renameSync(stage,path.join(root,'detached-owned-stage'));fs.mkdirSync(stage,{mode:0o700});replacement=path.join(stage,'unrelated');fs.writeFileSync(replacement,'preserve');fs.writeFileSync(path.join(sourcePath,'dist/index.js'),'export const changed = true;');return r;}};
 await assert.rejects(installLocalDshBundle({sourcePath,storeRoot,runtimeModule}),e=>/source changed/.test(e.message)&&/cleanup ownership changed/.test(e.cleanupError?.message));assert.equal(fs.readFileSync(replacement,'utf8'),'preserve');
});
